package practice;

import java.io.IOException;
import java.io.InputStream;
import java.util.Locale;
import java.util.zip.GZIPInputStream;
import java.util.zip.InflaterInputStream;

/**
 * Decodes request bodies that clients upload to the ingest API, according to the request's
 * Content-Encoding header.
 */
public class BodyDecoder {

    /** The encodings the ingest API accepts. */
    public enum Codec { IDENTITY, GZIP, DEFLATE }

    /** Wraps the raw body in the decoder its Content-Encoding header asks for. */
    public InputStream decode(InputStream body, String contentEncoding) throws IOException {
        switch (codecFor(contentEncoding)) {
            case GZIP:
                return new GZIPInputStream(body);
            case DEFLATE:
                return new InflaterInputStream(body);
            default:
                return body;
        }
    }

    /**
     * The codec for a Content-Encoding header value. The value is null when the request had
     * no such header. An encoding the API doesn't accept throws IllegalArgumentException.
     */
    Codec codecFor(String contentEncoding) {
        if (contentEncoding == null) {
            return Codec.IDENTITY;
        }
        switch (contentEncoding.toLowerCase(Locale.ROOT)) {
            case "identity":
                return Codec.IDENTITY;
            case "gzip", "x-gzip":
                return Codec.GZIP;
            case "deflate":
                return Codec.DEFLATE;
            default:
                throw new IllegalArgumentException("unsupported Content-Encoding: " + contentEncoding);
        }
    }
}

package practice;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Locale;
import java.util.zip.GZIPOutputStream;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            Locale.setDefault(Locale.forLanguageTag("tr-TR"));
            BodyDecoder decoder = new BodyDecoder();
            System.out.println("GZIP: " + decoder.codecFor("GZIP"));
            System.out.println("IDENTITY on a Turkish server: " + decoder.codecFor("IDENTITY"));
            System.out.println("no header: " + decoder.codecFor(null));
            ByteArrayOutputStream packed = new ByteArrayOutputStream();
            try (GZIPOutputStream gz = new GZIPOutputStream(packed)) {
                gz.write("{\"sensor\":\"silo-2\",\"temp\":18.5}".getBytes(StandardCharsets.UTF_8));
            }
            byte[] body = decoder.decode(new ByteArrayInputStream(packed.toByteArray()), "x-gzip").readAllBytes();
            System.out.println("decoded body: " + new String(body, StandardCharsets.UTF_8));
            try {
                System.out.println("br: " + decoder.codecFor("br"));
            } catch (IllegalArgumentException refused) {
                System.out.println("br refused: " + refused.getMessage());
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

